using Npgsql;
using PGMS.PostgreSql;

internal static class IdentityColumnEditChecks
{
    private sealed record RejectAfterApply(IdentityColumnEdit Inner):IAdministrativeEdit
    {
        public string ToSql()=>Inner.ToSql();
        public Task ValidateAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken token=default)=>Inner.ValidateAsync(c,t,token);
        public async Task VerifyAppliedAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken token=default)
        {await Inner.VerifyAppliedAsync(c,t,token);throw new IOException("Synthetic verification failure after native identity change.");}
    }
    internal static async Task RunAsync(string connection,Action<bool,string> check)
    {
        string suffix=Guid.NewGuid().ToString("N"),schema="identity_edit_é\"_"+suffix,owner="identity_edit_owner_"+suffix,reader="identity_edit_reader_"+suffix;
        string qs=SqlIdentifier.Quote(schema),qo=SqlIdentifier.Quote(owner),qr=SqlIdentifier.Quote(reader),table=ObjectSql.Relation(schema,"target");
        await using var admin=new NpgsqlConnection(connection);await admin.OpenAsync();
        async Task Admin(string sql){await using var cmd=new NpgsqlCommand(sql,admin);await cmd.ExecuteNonQueryAsync();}
        string As(string role)=>new NpgsqlConnectionStringBuilder(connection){Username=role,Pooling=false}.ConnectionString;
        try
        {
            await Admin($"CREATE ROLE {qo} LOGIN;CREATE ROLE {qr} LOGIN;CREATE SCHEMA {qs} AUTHORIZATION {qo};GRANT USAGE ON SCHEMA {qs} TO {qr}");
            await using var client=new NpgsqlConnection(As(owner));await client.OpenAsync();
            async Task<object?> Scalar(string sql){await using var cmd=new NpgsqlCommand(sql,client);return await cmd.ExecuteScalarAsync();}
            var service=new AdministrativeEditService(As(owner));var inspect=new IdentityColumnService(As(owner));
            Task<IdentityColumnSnapshot> Read(string name="target",string column="id")=>inspect.InspectAsync(schema,name,column);
            async Task Refuse(IdentityColumnSnapshot snapshot,IdentityColumnOperation operation,long? value,string label)
            {bool refused=false;try{await service.ApplyAsync(new IdentityColumnEdit(snapshot,operation,value));}catch(InvalidOperationException ex)when(ex.Message.Contains("changed",StringComparison.Ordinal)){refused=true;}check(refused,label);}
            await Scalar($"CREATE TABLE {table}(id bigint NOT NULL,note text);INSERT INTO {table} VALUES(17,'first'),(27,'second')");
            var plain=await Read();
            check(plain.DatabaseOid>0 && plain.NamespaceOid>0 && plain.TableOid>0 && plain.Position==1 && plain.TypeOid==20 && !plain.HasIdentity && plain.Sequence is null,"Identity inspection binds exact database/table/namespace/column/type without inventing a sequence");
            check(new IdentityColumnEdit(plain,IdentityColumnOperation.AddByDefault).ToSql().Contains("ADD GENERATED BY DEFAULT AS IDENTITY",StringComparison.Ordinal),"Existing-column ADD identity scripts an explicit mode");
            await service.ApplyAsync(new IdentityColumnEdit(plain,IdentityColumnOperation.AddByDefault));
            var current=await Read();
            check(current.Generation=="d" && current.Sequence is{Oid:>0,TypeOid:20,Start:1,Increment:1},"ADD identity creates a bound underlying sequence without privileged catalog writes");
            check((string)(await Scalar($"SELECT string_agg(id::text,',' ORDER BY id) FROM {table}"))! =="17,27","Adding identity to an existing column preserves all existing values");
            check(Convert.ToInt64(await Scalar($"INSERT INTO {table}(note) VALUES('generated') RETURNING id"))==1,"New identity on existing column begins from its explicit default sequence configuration");
            check(Convert.ToInt64(await Scalar($"INSERT INTO {table}(id,note) VALUES(88,'explicit') RETURNING id"))==88,"BY DEFAULT permits explicit existing-column values");
            var beforeMode=current;await service.ApplyAsync(new IdentityColumnEdit(current,IdentityColumnOperation.SetAlways));current=await Read();
            check(current.Generation=="a" && current.Sequence==beforeMode.Sequence,"Changing generation preserves underlying sequence identity and configuration");
            await Refuse(beforeMode,IdentityColumnOperation.SetByDefault,null,"Stale generation snapshot refuses Apply after a concurrent mode change");
            bool explicitRefused=false;try{await Scalar($"INSERT INTO {table}(id,note) VALUES(89,'forbidden')");}catch(PostgresException ex)when(ex.SqlState=="428C9"){explicitRefused=true;}
            check(explicitRefused,"SET GENERATED ALWAYS affects actual subsequent INSERT behavior");
            await service.ApplyAsync(new IdentityColumnEdit(current,IdentityColumnOperation.Restart,100));
            check(await Read()==current,"Restart preserves inspected metadata and configuration without consuming a value");
            check(Convert.ToInt64(await Scalar($"INSERT INTO {table}(note) VALUES('restart') RETURNING id"))==100,"Explicit identity restart sets the next generated value");
            bool rolledBack=false;try{await service.ApplyAsync(new RejectAfterApply(new(current,IdentityColumnOperation.Restart,200)));}catch(IOException){rolledBack=true;}
            check(rolledBack && Convert.ToInt64(await Scalar($"INSERT INTO {table}(note) VALUES('after rollback') RETURNING id"))==101,"Verification failure rolls back native RESTART rather than leaving setval-style side effects");
            string rows=(string)(await Scalar($"SELECT string_agg(id::text,',' ORDER BY id) FROM {table}"))!;uint oldSequence=current.Sequence!.Oid;
            await service.ApplyAsync(new IdentityColumnEdit(current,IdentityColumnOperation.Drop));var dropped=await Read();
            check(!dropped.HasIdentity && dropped.Sequence is null && !dropped.Nullable,"DROP identity removes generation but preserves NOT NULL");
            check((string)(await Scalar($"SELECT string_agg(id::text,',' ORDER BY id) FROM {table}"))! ==rows,"DROP identity preserves existing row values");
            check((bool)(await Scalar($"SELECT NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid={oldSequence})"))!,"DROP identity removes only the inspected internal sequence");
            bool required=false;try{await Scalar($"INSERT INTO {table}(note) VALUES('missing id')");}catch(PostgresException ex)when(ex.SqlState=="23502"){required=true;}
            check(required,"After DROP identity, omitted values still obey the retained NOT NULL constraint");
            await service.ApplyAsync(new IdentityColumnEdit(dropped,IdentityColumnOperation.AddAlways));var recreated=await Read();
            check(recreated.Generation=="a" && recreated.Sequence!.Oid!=oldSequence,"Re-adding identity creates a distinct sequence identity");
            await Refuse(current,IdentityColumnOperation.SetByDefault,null,"Old sequence snapshot cannot alter a same-column identity recreated with another sequence");
            var sequence=recreated.Sequence!;await Scalar($"ALTER SEQUENCE {ObjectSql.Relation(sequence.Schema,sequence.Name)} INCREMENT BY 2");
            await Refuse(recreated,IdentityColumnOperation.Restart,100,"Changed underlying sequence configuration refuses stale restart");
            current=await Read();await service.ApplyAsync(new IdentityColumnEdit(current,IdentityColumnOperation.Restart,10));
            check(Convert.ToInt64(await Scalar($"INSERT INTO {table}(note) VALUES('fresh restart') RETURNING id"))==10,"Reinspection permits restart after explicit sequence configuration change");
            await Refuse(current with{DatabaseOid=current.DatabaseOid+1},IdentityColumnOperation.SetByDefault,null,"Database OID mismatch refuses identity change");
            await Refuse(current with{NamespaceOid=current.NamespaceOid+1},IdentityColumnOperation.SetByDefault,null,"Namespace OID mismatch refuses identity change");
            await Scalar($"CREATE TABLE {ObjectSql.Relation(schema,"race")}(id int GENERATED ALWAYS AS IDENTITY)");var stale=await Read("race");
            await Scalar($"ALTER TABLE {ObjectSql.Relation(schema,"race")} DROP COLUMN id;ALTER TABLE {ObjectSql.Relation(schema,"race")} ADD COLUMN id int GENERATED ALWAYS AS IDENTITY");
            await Refuse(stale,IdentityColumnOperation.SetByDefault,null,"Same-name recreated column with new attnum refuses identity change");
            var afterColumn=await Read("race");bool parentMismatch=false;try{await inspect.InspectAsync(schema,"race","id",expectedTableOid:stale.TableOid,expectedPosition:stale.Position);}catch(InvalidOperationException){parentMismatch=true;}
            check(parentMismatch && afterColumn.Position!=stale.Position,"Parent selection cannot silently transfer to a replacement column during fresh inspection");
            await Scalar($"ALTER TABLE {ObjectSql.Relation(schema,"race")} RENAME TO original;CREATE TABLE {ObjectSql.Relation(schema,"race")}(id int GENERATED ALWAYS AS IDENTITY)");
            await Refuse(afterColumn,IdentityColumnOperation.Drop,null,"Same-name table replacement refuses DROP identity");
            bool bounds=false;try{new IdentityColumnEdit(await Read("race"),IdentityColumnOperation.Restart,long.MaxValue).ToSql();}catch(ArgumentException){bounds=true;}
            check(bounds,"Restart outside inspected integer sequence bounds is refused before SQL");
            foreach(string definition in new[]{"id integer","id integer NOT NULL DEFAULT 17","id text NOT NULL","base integer,id integer GENERATED ALWAYS AS (base+1) STORED"})
            {
                string name="invalid_"+Guid.NewGuid().ToString("N");await Scalar($"CREATE TABLE {ObjectSql.Relation(schema,name)}({definition})");var invalid=await Read(name);
                bool refused=false;try{new IdentityColumnEdit(invalid,IdentityColumnOperation.AddByDefault).ToSql();}catch(ArgumentException){refused=true;}
                check(refused,"Identity ADD refuses nullable/default/non-integer/generated column without altering it");
            }
            bool authority=false;try{await new AdministrativeEditService(As(reader)).ApplyAsync(new IdentityColumnEdit(await Read(),IdentityColumnOperation.SetByDefault));}catch(PostgresException ex)when(ex.SqlState=="42501"){authority=true;}
            check(authority,"Identity DDL respects table ownership for a limited reader");
        }
        finally{await Admin($"DROP SCHEMA IF EXISTS {qs} CASCADE;DROP ROLE IF EXISTS {qr};DROP ROLE IF EXISTS {qo}");}
    }
}
